(async () => {
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const out = { url: location.origin + location.pathname, desktop: '__TAURI_INTERNALS__' in window };
  if (!document.querySelector('.pj-title')) {
    const cards = [...document.querySelectorAll('.tb-project-main')];
    if (cards[0]) { cards[0].click(); await sleep(3000); }
  }
  out.title = document.querySelector('.pj-title')?.textContent || null;
  const btn = [...document.querySelectorAll('.pj-head-actions > button')].find((b) => b.textContent.includes('保存作品文件'));
  out.hasButton = !!btn;
  btn.click();
  // 原生对话框由外部脚本用 SendKeys 填路径并回车，这里等提示出现
  for (let i = 0; i < 60; i++) {
    await sleep(500);
    const t = document.querySelector('.pj-toast')?.textContent || '';
    if (t) { out.toast = t; break; }
  }
  out.toastFinal = document.querySelector('.pj-toast')?.textContent || null;
  return JSON.stringify(out);
})()
